(()=>{'use strict';
const M=TrialStoryModel,$=id=>document.getElementById(id),key='plant-lab-trial-story-v1',main=M.stats(M.values),practice=M.stats(M.noisy),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let state,storage=true;try{state=M.restore(localStorage.getItem(key));}catch{state=M.fresh();storage=false;}
const u={step:state.current,session:state,selected:null,harvesting:null,harvestPhase:0,readyForWeigh:false,weighPhase:0,historyProgress:state.e.history?1:0,sampleN:4,compareN:4,standardVisual:state.e.standard,batch:null,batchPhase:1,tail:state.answers.tail||null,pending:null,message:'',wrong:false};
const scene=TrialStoryScene.create($('scene'),()=>u),world=scene.world;
u.onPlot=i=>selectPlot(i);
const btn=(action,label,extra='')=>`<button data-action="${action}" ${extra}>${label}</button>`;
const f=(x,d=2)=>Number(x).toFixed(d),formula=(text,note='')=>`<div class="formula-card">${text}${note?`<small>${note}</small>`:''}</div>`;
function save(){if(M.unlocked(state)===15&&!state.completedAt)state.completedAt=new Date().toISOString();try{localStorage.setItem(key,JSON.stringify(state));}catch{storage=false;}}
function persistRender(){save();render();}
function busy(){return !!u.pending;}
function animate(type,duration,done){if(busy())return;u.message='';u.wrong=false;if(reduced){done();persistRender();return;}world.paused=false;$('motion').textContent='暂停动画';$('motion').setAttribute('aria-pressed','true');u.pending={type,duration,elapsed:0,done};render();}
world.update=dt=>{if(u.pending&&!world.paused){const p=u.pending;p.elapsed+=dt;const t=Math.min(1,p.elapsed/p.duration),smooth=t*t*(3-2*t);if(p.type==='history')u.historyProgress=smooth;if(p.type==='harvest')u.harvestPhase=smooth;if(p.type==='weigh')u.weighPhase=smooth;if(p.type==='batch')u.batchPhase=smooth;if(p.type==='standard')u.standardVisual=u.standardFrom+(u.standardTo-u.standardFrom)*smooth;
 if(t>=1){u.pending=null;p.done();persistRender();}}
};
function recordSheet(){return `<div class="record-sheet"><div class="record-title">2024级农资班 · 四张收获单</div>${M.values.map((v,i)=>`<div><span>重复${i+1}</span><b>${v} 公斤/亩</b></div>`).join('')}</div>`;}
function statsGrid(s){return `<div class="numeric-grid"><div><small>平均亩产 x̄</small><b>${f(s.mean,0)}</b></div><div><small>样本标准差 s</small><b>${f(s.s)}</b></div><div><small>估计标准误差 s/√n</small><b>${f(s.se)}</b></div><div><small>四次重复 · df＝3</small><b>${f(s.t)} <em>t值</em></b></div></div>`;}
function activity(){switch(u.step){
 case 0:return `<div class="activity-row">${btn('history',state.e.history?'历史记录已展开 ✓':'展开历史收获记录',`${state.e.history?'disabled ':''}class="primary"`)}</div><div class="activity-meta">历史基准 μ₀＝500公斤/亩<br>试验前约定：检验是否提高，α＝0.05</div>`;
 case 1:return `<div class="plot-buttons">${M.values.map((v,i)=>btn('plot',`<span>重复${i+1}${state.e.harvest.includes(i)?' ✓':''}</span>${state.e.harvest.includes(i)?`<strong>${v}公斤/亩</strong>`:'<small>点击小区收获</small>'}`,`data-plot="${i}" class="${state.e.harvest.includes(i)?'done':''} ${u.selected===i?'selected':''}" ${state.e.harvest.includes(i)?'disabled':''}`)).join('')}</div>${u.selected!==null&&!state.e.harvest.includes(u.selected)?`<div class="activity-row">${btn('weigh',busy()?'收获 / 称重中…':'称重并记录亩产',`${!u.readyForWeigh||busy()?'disabled':''} class="primary"`)}</div><div class="activity-meta">小区面积20 m² · 统一含水率（示例）${u.readyForWeigh?` · 脱粒后籽粒已送达秤台`:''}</div>`:''}<div class="activity-meta">已完成 ${state.e.harvest.length} / 4 个独立小区。<br>小区是试验重复，单株玉米不是独立重复。</div>`;
 case 2:return recordSheet();
 case 3:return formula('550 − 500 ＝ 50','平均亩产高出50公斤；这一步只记录你的初判。');
 case 4:return `<div class="activity-row">${btn('sample','抽取四个小区','class="primary"')}${state.e.samples.length>=3?btn('many','再模拟40组'):''}</div><div class="activity-meta">已完成 ${state.e.samples.length} 组 · 至少亲手抽取3组<br>每四个观测，只生成一个均值。</div>${u.batch?`<div class="samples-chips">${u.batch.values.map(v=>`<span>${f(v,1)}</span>`).join('')}</div>`:''}${formula('X̄ 的标准误差＝σ / √n','蓝：单个小区　绿：四个小区的均值')}`;
 case 5:return `<div class="range-presets">${[1,4,16].map(n=>btn('sample-n',`n＝${n}`,`data-n="${n}" class="${u.sampleN===n?'active':''}"`)).join('')}</div><div class="visited-chip">已观察：${state.e.sampleN.map(n=>'n='+n).join('、')}</div>${formula(`SE＝40 / √${u.sampleN}＝${f(40/Math.sqrt(u.sampleN),0)}`,'动画中单个小区σ＝40；改变的是模拟重复数。')}`;
 case 6:return `<div class="activity-row">${btn('standard',state.e.standard===0?'① 减去基准500':state.e.standard===1?'② 除以标准误差':'重新播放标准化',`class="primary"`)}</div>${formula(state.e.standard<1?'X̄':state.e.standard===1?'X̄ − 500':'Z＝(X̄ − 500) / (σ/√n)','已知σ的演示：σ＝40，n＝4，SE＝20。')}`;
 case 7:return `${recordSheet()}<div class="activity-row">${btn('estimate',state.e.estimated?'已估计 ✓':'用四个小区估计','class="primary"')}</div>${state.e.estimated?formula('s≈25.82<br>s / √4≈12.91','本次试验σ未知；用样本估计，单位为公斤/亩。'):''}`;
 case 8:return `<div class="activity-row">${btn('variance','再抽一组，估计分母','class="primary"')}</div><div class="activity-meta">已比较 ${state.e.runs.length} 组 · 至少操作3次</div>${state.e.runs.length?`<div class="samples-chips">${state.e.runs.slice(-6).map(v=>`<span>SE≈${f(M.stats(v).se,1)}</span>`).join('')}</div>`:''}${formula('T＝(X̄ − 500) / (s/√n)','Gosset（Student）研究了小样本均值的不确定性。')}`;
 case 9:return `<label class="range-label" for="compare-n">模拟样本量 n <output id="n-out">${u.compareN}</output></label><label class="range-label"><input id="compare-n" type="range" min="4" max="100" step="1" value="${u.compareN}" aria-label="模拟样本量"></label><div class="range-presets">${[4,10,30,100].map(n=>btn('compare-n',String(n),`data-n="${n}" class="${u.compareN===n?'active':''}"`)).join('')}</div><div class="formula-card" id="df-formula">df＝${u.compareN}−1＝${u.compareN-1}<small>蓝：标准正态　橙：t分布</small></div><div class="visited-chip" id="df-visited">${dfVisited()}</div><details class="activity-meta"><summary>为什么减1？</summary><div class="deviations"><span>−30</span><span>−10</span><span>＋10</span><span class="dependent">＋30</span></div>四个偏差之和为0；前三个确定后，第四个也确定了。</details>`;
 case 10:return `<div class="activity-row">${btn('calculate','计算本次标准化统计量','class="primary"')}</div>${state.e.calculated?`${statsGrid(main)}${formula('(550 − 500) / 12.91','回到实际试验：n＝4，df＝3。')}`:formula('高出50公斤 ÷ 估计标准误差','先点击计算，再选择结果。')}`;
 case 11:return `${formula('t≈3.87　df＝3','试验前约定的方向：是否提高 → 右尾')}${state.answers.tail==='right'?`<div class="activity-row">${btn('probability',state.e.probability?'右尾概率已计算 ✓':'计算右尾概率','class="primary"')}</div>`:''}${state.e.probability?formula('p≈0.0152＝1.52%','P(T₃ ≥ 3.87)，尾部延伸至＋∞。'):''}`;
 case 12:return formula('p≈1.52%','基准假设：平均水平仍为500；求的是这样或更偏高的T值。');
 case 13:return `${formula('0.0152 ＜ 0.05','观察到的p值 ＜ 试验前约定的α')}${formula('3.87 ＞ 2.353','观察到的t值 ＞ 右尾5%临界值')}`;
 case 14:return `<div class="record-sheet"><div class="record-title">另一组练习数据 · 均值仍为550</div>${M.noisy.map((v,i)=>`<div><span>重复${i+1}</span><b>${v} 公斤/亩</b></div>`).join('')}</div><div class="activity-row">${btn('noisy',state.e.noisy?'重新计算 ✓':'重新计算标准误差与概率','class="primary"')}</div>${state.e.noisy?`${statsGrid(practice)}${formula(`p≈${f(practice.p,3)} ＞ 0.05`,'平均值没变，重复间的波动变大了。')}`:''}`;
 case 15:return `<div class="finish-card"><h3>这次判断，你完成了。</h3><p>初判：${voteLabel()}</p><p>最终：相较历史基准，在0.05水平下显著提高。</p><p>x̄＝550　s≈25.82<br>SE≈12.91　t≈3.87　p≈0.0152</p></div><div class="finish-path">历史基准 → 四次重复 → <b>均值抽样分布</b> → 标准误差 → <b>t分布</b> → 右尾概率 → 显著性判断</div><div class="activity-row">${btn('download','下载我的学习记录','class="primary"')}${btn('review','回看四个小区')}</div><div class="activity-meta">${storage?'进度已保存在本浏览器。':'当前浏览器不允许保存；可以下载记录。'}<br>同样的均值，可能因分散程度不同而得到不同结论。</div>`;
 default:return '';
}}
function voteLabel(){return M.steps[3].options.find(x=>x[0]===state.answers.vote)?.[1]||'未记录';}
function dfVisited(){return `已比较：${state.e.dfN.includes(4)?'n＝4 ✓':'n＝4 ○'}　${state.e.dfN.some(n=>n>=30)?'n≥30 ✓':'n≥30 ○'}`;}
const hints=['先展开历史记录，再完成选择。','逐块点击收获，再称重并记录，共四个小区。','根据四张收获单计算，再选择。','任一初判都可继续，结尾再回看。','至少抽取3组，再选择比较对象。','观察n＝1、4、16，再判断宽度。','完成两步标准化动画，再选择。','先计算样本估计，再选择。','至少比较3组的估计标准误差，再选择。','观察n＝4及n≥30，再选择。','先计算统计量，再选择。','选对尾部并计算概率，才能继续。','完成概率含义的判断。','完成显著性结论的判断。','重新计算练习数据，再作出判断。','15个任务已完成，可回看任一场景。'];
function renderNavigation(){const limit=M.unlocked(state),done=M.passed(state,u.step);$('acts').innerHTML=M.acts.map((a,i)=>{const first=M.steps.find(s=>s.act===i).id,next=M.steps.find(s=>s.act===i+1)?.id||16;return `<button data-act="${i}" class="${M.steps[u.step].act===i?'active':''} ${limit>=next?'complete':''}" ${first>limit||busy()?'disabled':''} ${M.steps[u.step].act===i?'aria-current="step"':''}><i>${String(i+1).padStart(2,'0')}</i><span>${a}</span></button>`}).join('');$('step-dots').innerHTML=M.steps.map(s=>`<button data-step="${s.id}" aria-label="任务${s.id+1}：${s.title}" ${s.id>limit||busy()?'disabled':''} class="${s.id<u.step||M.passed(state,s.id)?'passed':''} ${s.id===u.step?'active':''}" ${s.id===u.step?'aria-current="step"':''}></button>`).join('');$('prev').disabled=u.step===0||busy();$('next').disabled=!done||busy();$('next').textContent=u.step===15?'已完成全部任务 ✓':done?'下一步 →':'完成本步后继续 →';$('task-status').textContent=u.step===15?'已完成':busy()?'操作进行中':done?'本步已完成 ✓':'等待你的操作';$('gate-hint').textContent=busy()?(world.paused?'动画已暂停，点击场景中的“继续动画”。':'正在演示，完成后继续。'):hints[u.step];}
function renderQuiz(){const s=M.steps[u.step];$('quiz').hidden=!s.key;if(!s.key){$('feedback').textContent=u.message;return;}$('question').textContent=s.question;
 const activityReady=M.ready(state,u.step)||u.step===11,selected=state.answers[s.key],ok=M.correct(state,s.key),done=M.passed(state,u.step);
 $('choices').innerHTML=s.options.map(([id,text],i)=>`<button data-choice="${id}" data-letter="${String.fromCharCode(65+i)}" class="${id===selected?'selected '+(ok?'correct':'wrong'):''}" ${!activityReady||busy()||done?'disabled':''} aria-pressed="${id===selected}">${text}</button>`).join('');
 const wrong=selected&&!ok;$('feedback').className=wrong||u.wrong?'wrong':'';$('feedback').textContent=u.message||(ok?s.feedback:wrong?wrongHint(s.key):'');}
function wrongHint(q){return {history:'500是长期中心。看看分布里是否还有高低不同的记录。',mean:'先把四个产量相加，再除以4。',reference:'550由四个小区取平均得到；看看绿色点怎样形成。',width:'比较绿色曲线的宽度，尤其是n＝1和n＝16。',unit:'现在判断的是平均值，应使用平均值自己的波动尺度。',estimate:'平均值比单个观测更稳定，估计标准误差还需要除以√n。',distribution:'用样本估计的分母会变，标准正态分布不能反映这份额外的不确定性。',converge:'请把样本量从4调到100，比较两条曲线的尾部。',statistic:'50除以12.91，约为3.87。',tail:'“是否提高”关注更偏高的T值，请看3.87右侧。',meaning:'先假定均值仍为500且模型成立，再考虑统计量的尾部概率。',conclusion:'p＜α，提供了显著提高的证据；小概率仍然可能发生。',challenge:'练习数据的p约为0.074，大于0.05；这不等于证明没有效果。'}[q]||'再观察图形，试一次。';}
function render(){const s=M.steps[u.step];state.current=u.step;u.session=state;$('task-index').textContent=`任务 ${String(u.step+1).padStart(2,'0')} / 16`;$('task-title').textContent=s.title;$('task-intro').textContent=s.intro;$('activity').innerHTML=activity();$('scene-kicker').textContent=`${String(s.act+1).padStart(2,'0')} / ${M.acts[s.act]}`;
 const titles=['无数次收获，留下一个500','2024级农资班的四个小区','四张收获单，一个平均值','高出50公斤，算不算意外？','四个点，汇成一个均值','均值的分布，为什么更瘦？','同一偏离，换成标准单位','未知的σ，用样本来估计','估计的分母，每次都会变','尾部的差别，随自由度改变','高出几个估计标准误差？','从3.87向右，寻找概率','1.52%，到底在说什么？','把概率，放进判断规则','一样的550，不一样的波动','从一场收获，到一次判断'];$('scene-title').textContent=titles[u.step];
 $('scene-subtitle').textContent=u.step<4||u.step===15?'玉米 · 一个处理 · 四次独立重复':u.step===4||u.step===5?'同一条产量数轴：蓝色X，绿色X̄':u.step===6?'先减去基准，再除以平均值的标准误差':u.step===9?'同一坐标系 · 同一尾部位置 · 改变样本量':'历史基准500 · 当前试验n＝4 · 右尾检验';
 let badges=u.step<4?['历史均值<strong>500</strong>','检验方向<strong>提高 →</strong>','事先约定<strong>α＝0.05</strong>']:u.step<6?['蓝：单个小区','绿：一组均值','模拟 σ＝40']:u.step===6?['已知σ的演示','n＝4 · SE＝20']:u.step===9?[`n＝${u.compareN}`,`df＝${u.compareN-1}`]:['实际试验 n＝4','df＝3','σ未知 → 用s估计'];
 $('scene-badges').innerHTML=badges.map(s=>`<span>${s}</span>`).join('');$('scene-note').textContent=u.step===4||u.step===5?'抽样动画以σ＝40演示原理；本次试验的总体σ未知。':u.step===6?'这一步展示已知σ时的Z；下一步回到实际试验，用四个小区估计标准误差。':u.step===8?'Gosset / Student：原始产量采用正态模型，改用t分布的是标准化统计量。':u.step===9?'橙色t曲线自由度小时尾部更厚；样本增多后逐渐接近蓝色标准正态。':u.step===11||u.step===12?'尾部延伸至＋∞；概率包含本次及更偏高的统计量，不是恰好550的概率。':u.step===15?'相对历史基准的统计判断，仍需结合年份、天气与地力的可比性。':'教学示例 · 独立小区 · 正态总体模型';
 renderQuiz();renderNavigation();
}
function go(i){if(busy()||!M.navigate(state,i))return;u.step=i;u.message='';u.wrong=false;u.tail=state.answers.tail||null;u.selected=null;u.readyForWeigh=false;u.harvesting=null;u.batch=null;if(i===5)u.sampleN=4;if(i===9)u.compareN=4;if(i===6)u.standardVisual=state.e.standard;scene.reset();if(i>=4&&i!==15){world.camera.yaw=-.12;world.camera.pitch=.25;}persistRender();if(innerWidth<=760){document.querySelector('.visual').scrollIntoView({behavior:'auto',block:'start'});}else{document.querySelector('.workbench').scrollTop=0;}$('task-title').setAttribute('tabindex','-1');$('task-title').focus({preventScroll:true});}
function selectPlot(i){if(busy()||u.step!==1||state.e.harvest.includes(i))return;u.selected=i;u.harvesting=i;u.readyForWeigh=false;u.harvestPhase=0;animate('harvest',1.15,()=>{u.harvestPhase=1;u.readyForWeigh=true;u.harvesting=null;});}
function compareN(n){if(u.step!==9||busy())return;u.compareN=Math.max(4,Math.min(100,Math.round(n)));if(!state.e.dfN.includes(u.compareN))state.e.dfN.push(u.compareN);save();$('n-out').value=String(u.compareN);$('df-formula').innerHTML=`df＝${u.compareN}−1＝${u.compareN-1}<small>蓝：标准正态　橙：t分布</small>`;$('df-visited').textContent=dfVisited();document.querySelectorAll('[data-action="compare-n"]').forEach(b=>b.classList.toggle('active',Number(b.dataset.n)===u.compareN));$('scene-badges').innerHTML=`<span>n＝${u.compareN}</span><span>df＝${u.compareN-1}</span>`;renderQuiz();renderNavigation();}
function download(){const payload={resource:'玉米产量显著提高了吗',version:1,completed:!!state.completedAt,completedAt:state.completedAt,initialVote:voteLabel(),completedTasks:M.unlocked(state),totalTasks:15,trial:{values:M.values,...main},practice:{values:M.noisy,...practice},attempts:state.attempts};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='玉米试验学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
$('activity').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled||busy())return;switch(b.dataset.action){
 case 'history':animate('history',1.7,()=>{state.e.history=true;u.historyProgress=1;});break;
 case 'plot':selectPlot(Number(b.dataset.plot));break;
 case 'weigh':if(u.selected===null||!u.readyForWeigh)return;u.weighPhase=0;animate('weigh',.95,()=>{state.e.harvest.push(u.selected);u.message=`重复${u.selected+1}：${f(M.values[u.selected]*.03)}公斤 ÷ 20m² × 666.67 ≈ ${M.values[u.selected]}公斤/亩。`;u.readyForWeigh=false;});break;
 case 'sample':u.batch=M.sample(4);u.batchPhase=0;animate('batch',1.05,()=>{state.e.samples.push(u.batch.values);u.batchPhase=1;});break;
 case 'many':for(let i=0;i<40;i++)state.e.samples.push(M.sample(4).values);state.e.samples=state.e.samples.slice(-200);persistRender();break;
 case 'sample-n':u.sampleN=Number(b.dataset.n);if(!state.e.sampleN.includes(u.sampleN))state.e.sampleN.push(u.sampleN);persistRender();break;
 case 'standard':u.standardFrom=state.e.standard===2?0:state.e.standard;u.standardTo=state.e.standard===2?2:state.e.standard+1;u.standardVisual=u.standardFrom;animate('standard',u.standardTo-u.standardFrom>1?2.6:1.3,()=>{state.e.standard=u.standardTo;u.standardVisual=u.standardTo;});break;
 case 'estimate':state.e.estimated=true;persistRender();break;
 case 'variance':animate('variance',.5,()=>{state.e.runs.push(M.sample(4).values);state.e.runs=state.e.runs.slice(-30);});break;
 case 'compare-n':compareN(Number(b.dataset.n));$('compare-n').value=String(u.compareN);break;
 case 'calculate':state.e.calculated=true;persistRender();break;
 case 'probability':if(state.answers.tail!=='right')return;state.e.probability=true;persistRender();break;
 case 'noisy':state.e.noisy=true;persistRender();break;
 case 'download':download();break;
 case 'review':go(1);break;
 }});
$('activity').addEventListener('input',e=>{if(e.target.id==='compare-n')compareN(Number(e.target.value));});
$('choices').addEventListener('click',e=>{const b=e.target.closest('[data-choice]');if(!b||b.disabled||busy())return;const s=M.steps[u.step];M.answer(state,s.key,b.dataset.choice);if(u.step===11)u.tail=b.dataset.choice;u.message='';u.wrong=false;persistRender();});
$('prev').onclick=()=>go(u.step-1);$('next').onclick=()=>{if(M.passed(state,u.step))go(u.step+1)};
$('acts').onclick=e=>{const b=e.target.closest('[data-act]');if(b&&!b.disabled)go(M.steps.find(s=>s.act===Number(b.dataset.act)).id)};
$('step-dots').onclick=e=>{const b=e.target.closest('[data-step]');if(b&&!b.disabled)go(Number(b.dataset.step))};
$('view-front').onclick=()=>scene.front();$('view-reset').onclick=()=>scene.reset();$('motion').onclick=()=>{world.paused=!world.paused;$('motion').textContent=world.paused?'继续动画':'暂停动画';$('motion').setAttribute('aria-pressed',String(!world.paused));renderNavigation();};
$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});else document.documentElement.requestFullscreen?.().catch(()=>{})};
$('model-info').onclick=()=>$('info-dialog').showModal();$('restart').onclick=()=>$('restart-dialog').showModal();document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('confirm-restart').onclick=()=>{$('restart-dialog').close();u.pending=null;state=M.fresh();Object.assign(u,{session:state,step:0,historyProgress:0,selected:null,harvesting:null,readyForWeigh:false,harvestPhase:0,weighPhase:0,sampleN:4,compareN:4,standardVisual:0,batch:null,tail:null,message:'',wrong:false});scene.reset();persistRender();};
window.addEventListener('pagehide',save);
Object.defineProperty(window,'trialStoryDiagnostics',{get:()=>({step:u.step,unlocked:M.unlocked(state),passed:M.passed(state,u.step),ready:M.ready(state,u.step),busy:busy(),paused:world.paused,session:JSON.parse(JSON.stringify(state)),main,practice,simulation:{sampleN:u.sampleN,compareN:u.compareN,batch:u.batch,standard:u.standardVisual},camera:{...world.camera},plotHits:scene.hits})});
if(u.step>=4&&u.step!==15){world.camera.yaw=-.12;world.camera.pitch=.25;}
render();save();
})();
